public final class RomanNumeral {
    private RomanNumeral() {}

    /** Parse a well-formed Roman numeral ("MCMXCIV" -> 1994). Empty input or
     *  any character outside MDCLXVI throws IllegalArgumentException. */
    public static int toInt(String s) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("empty numeral");
        }
        int total = 0;
        for (int i = 0; i < s.length(); i++) {
            int value = valueOf(s.charAt(i));
            if (i + 1 < s.length() && value < valueOf(s.charAt(i + 1))) {
                total -= value;
            } else {
                total += value;
            }
        }
        return total;
    }

    private static int valueOf(char c) {
        switch (c) {
            case 'M': return 1000;
            case 'D': return 500;
            case 'C': return 100;
            case 'L': return 50;
            case 'X': return 10;
            case 'V': return 5;
            case 'I': return 1;
            default: throw new IllegalArgumentException("invalid character: " + c);
        }
    }
}

