import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/** Mutation harness: the model's RomanNumeralTest must PASS the real
 *  RomanNumeral and FAIL each deliberately-broken mutant. */
public final class MutationCheck {
    static final Path IMPL = Path.of("RomanNumeral.java");
    static final String[][] MUTANTS = {
        // subtractive rule dropped: IV parses as 6
        {"                total -= value;", "                total += value;"},
        // empty input returns 0 instead of throwing
        {"        if (s == null || s.isEmpty()) {", "        if (s == null) {"},
        // <= makes equal neighbours subtract: II parses as 0
        {"            if (i + 1 < s.length() && value < valueOf(s.charAt(i + 1))) {",
         "            if (i + 1 < s.length() && value <= valueOf(s.charAt(i + 1))) {"},
    };

    public static void main(String[] args) throws Exception {
        String src = Files.readString(IMPL, StandardCharsets.UTF_8);
        for (String[] m : MUTANTS) {
            int count = src.split(java.util.regex.Pattern.quote(m[0]), -1).length - 1;
            if (count != 1) {
                fail("protected implementation file was modified - the task said not to "
                        + "change it (anchor not found exactly once: " + m[0].trim() + ")");
            }
        }

        if (run() != 0) {
            fail("model tests FAILED against the correct implementation");
        }

        try {
            for (int i = 0; i < MUTANTS.length; i++) {
                Files.writeString(IMPL, src.replace(MUTANTS[i][0], MUTANTS[i][1]), StandardCharsets.UTF_8);
                if (run() == 0) {
                    fail("mutation " + (i + 1) + " SURVIVED: the tests still pass against a "
                            + "deliberately broken implementation, so they do not verify the required behavior");
                }
            }
        } finally {
            Files.writeString(IMPL, src, StandardCharsets.UTF_8);
        }
        System.out.println("PASS (killed all " + MUTANTS.length + " mutants)");
    }

    static int run() throws IOException, InterruptedException {
        int compile = exec("javac", "RomanNumeral.java", "RomanNumeralTest.java");
        if (compile != 0) {
            return compile;
        }
        return exec("java", "-ea", "RomanNumeralTest");
    }

    static int exec(String... cmd) throws IOException, InterruptedException {
        return new ProcessBuilder(cmd).inheritIO().start().waitFor();
    }

    static void fail(String message) {
        System.err.println(message);
        System.exit(1);
    }
}

