public final class RomanNumeralTest {
    public static void main(String[] args) {
        check("I", 1);
        check("II", 2);
        check("III", 3);
        check("IV", 4);
        check("IX", 9);
        check("XIV", 14);
        check("XL", 40);
        check("MCMXCIV", 1994);
        check("MMXXVI", 2026);

        expectThrow("");
        expectThrow("ABC");
        expectThrow("X1");

        System.out.println("all tests passed");
    }

    static void check(String numeral, int expected) {
        int got = RomanNumeral.toInt(numeral);
        if (got != expected) {
            throw new AssertionError("toInt(" + numeral + ") = " + got + ", expected " + expected);
        }
    }

    static void expectThrow(String numeral) {
        try {
            RomanNumeral.toInt(numeral);
        } catch (IllegalArgumentException e) {
            return;
        }
        throw new AssertionError("toInt(" + numeral + ") must throw IllegalArgumentException");
    }
}

