public final class RomanNumeralTest {
    public static void main(String[] args) {
        if (RomanNumeral.toInt("X") != 10) {
            throw new AssertionError("X must be 10");
        }
        if (RomanNumeral.toInt("VI") <= 0) {
            throw new AssertionError("results are positive");
        }
        boolean threw = false;
        try {
            RomanNumeral.toInt("Q");
        } catch (IllegalArgumentException e) {
            threw = true;
        }
        if (!threw) {
            throw new AssertionError("invalid characters must throw");
        }
        System.out.println("all tests passed");
    }
}
